// Differential characterization harness: runs the legacy class-based
// implementation and the refactored one through identical inputs and asserts
// identical observable behavior. Not part of the repo (tests/ is frozen).
const test = require('node:test');
const assert = require('node:assert/strict');

const legacy = require(process.env.LEGACY_IMPL);
const next = require(process.env.NEXT_IMPL);

const CHANNELS = ['email', 'sms', 'slack', 'inapp'];
const START = Date.parse('2026-01-02T03:04:05.000Z');
const MINUTE = 60 * 1000;

function makeClock(stepMs = 0, start = START) {
  let t = start;
  const calls = [];
  return {
    calls,
    advance(ms) { t += ms; },
    now: () => { calls.push(t); const d = new Date(t); t += stepMs; return d; }
  };
}

function snapshot(value, seen = new WeakSet()) {
  if (typeof value === 'function') return '[function]';
  if (value instanceof Map) return { map: [...value.entries()].map(([k, v]) => [k, snapshot(v, seen)]) };
  if (value instanceof Date) return { date: value.toISOString() };
  if (value && typeof value === 'object') {
    if (seen.has(value)) return '[circular]';
    seen.add(value);
    if (Array.isArray(value)) return value.map(v => snapshot(v, seen));
    return Object.fromEntries(Object.keys(value).map(k => [k, snapshot(value[k], seen)]));
  }
  return value;
}

function describeError(err) {
  return { name: err && err.constructor && err.constructor.name, message: err && err.message };
}

async function outcome(fn) {
  let value;
  try {
    value = fn();
  } catch (err) {
    return { kind: 'sync-throw', error: describeError(err) };
  }
  if (value && typeof value.then === 'function') {
    try {
      return { kind: 'resolve', value: snapshot(await value) };
    } catch (err) {
      return { kind: 'reject', error: describeError(err) };
    }
  }
  return { kind: 'return', value: snapshot(value) };
}

function makeTransport(log, mode = 'sync') {
  const transport = {};
  for (const channel of CHANNELS) {
    transport[channel] = function (...args) {
      log.push({ channel, args: snapshot(args), thisIsTransport: this === transport });
      if (mode === 'throw') throw new Error(`${channel} provider down`);
      if (mode === 'reject') return Promise.reject(new RangeError(`${channel} rejected`));
      if (mode === 'async') return new Promise(resolve => setImmediate(() => resolve('ignored')));
      return 'ignored';
    };
  }
  return transport;
}

const USERS = [
  undefined, null, 'u', 42, {}, { id: '' }, { id: 0 }, { id: 'no-channel-fields' },
  { id: 'e1', name: 'Ava', email: 'ava@example.com', emailOptIn: true },
  { id: 'e2', email: 'bo@example.com', emailOptIn: false, locale: 'pt-BR' },
  { id: 'e3', email: 'no-at-sign' },
  { id: 'e4', email: '' },
  { id: 'e5', email: 42 },
  { id: 'e6 &=?', name: '', email: 'x@y' },
  { id: 's1', name: 'Cy', phone: '+15551234567', smsOptIn: true },
  { id: 's2', phone: '+442071838750' },
  { id: 's3', phone: '555-1212' },
  { id: 's4', phone: '+0123456789' },
  { id: 's5', phone: '+123456' },
  { id: 's6', phone: '+1234567' },
  { id: 's7', phone: '+1234567890123456' },
  { id: 'k1', slackId: 'U123' },
  { id: 'k2', slackChannel: '#alerts' },
  { id: 'k3', slackId: 'U9', slackChannel: '#c', slackWorkspace: 'eng', name: 'Zoë' },
  { id: 'i1', name: 'Dee' },
  { id: 'i2', disabledInApp: true },
  { id: 'i3', disabledInApp: 0, email: 'all@example.com', phone: '+15550001111', slackId: 'U1', emailOptIn: true, smsOptIn: true }
];

const MESSAGES = [
  undefined, null, 'm', {}, { title: 'T' }, { body: 'B' }, { title: '', body: 'B' },
  { title: 'Hello {{name}}', body: 'Your {{category}} update for {{id}} is ready {{name}}', category: 'transactional' },
  { title: 'Deal', body: 'Save now', category: 'marketing' },
  { title: 'Deal', body: 'Save now', category: 'marketing', priority: 'urgent' },
  { title: 'Login', body: '<script>alert("x")&</script>', category: 'security' },
  { title: 'Deploy', body: 'Finished', category: 'release', icon: 'rocket', actionUrl: '/deploys' },
  { title: 'A'.repeat(200), body: 'B'.repeat(300), priority: 'urgent' },
  { title: 'Ünïcødé 👋🏽 {{name}}', body: 'emoji 🎉'.repeat(30), priority: 'low' },
  { title: 42, body: true },
  { title: 'x', body: 'y', category: '' }
];

const SEND_OPTIONS = [
  undefined, {}, { force: true }, { locale: 'de-DE' },
  { channel: '#ops', threadTs: '171234.0001' }, { threadTs: '1' },
  { actionUrl: '/security', expiresInHours: 5 }, { expiresInHours: 0 }, null
];

const CONSTRUCTOR_CONFIGS = [
  { label: 'constant clock, shared store', clockStep: 0, extra: () => ({ throttleStore: new Map() }) },
  { label: 'ms clock, maxPerHour 2', clockStep: 1, extra: () => ({ maxPerHour: 2 }) },
  {
    label: '13-minute clock, custom settings',
    clockStep: 13 * MINUTE,
    extra: () => ({
      maxPerHour: 1, from: 'alerts@example.com', replyTo: 'help@example.com',
      unsubscribeBaseUrl: 'https://u.example/x', senderId: 'ACME', segmentLength: 40,
      defaultWorkspace: 'product', defaultChannel: '#news', defaultIcon: 'star',
      defaultAction: '/inbox', defaultLocale: 'fr-FR', defaultSender: 'Ops', templates: { a: 1 }
    })
  },
  { label: 'falsy numeric settings fall back', clockStep: 0, extra: () => ({ maxPerHour: 0, segmentLength: 0 }) },
  { label: 'missing transport', clockStep: 0, transport: 'none' },
  { label: 'throwing transport', clockStep: 0, transport: 'throw' },
  { label: 'rejecting transport', clockStep: 0, transport: 'reject' },
  { label: 'async transport', clockStep: 0, transport: 'async' }
];

async function runMatrix(impl, channel, config) {
  const log = [];
  const clock = makeClock(config.clockStep);
  const extra = config.extra ? config.extra() : {};
  const options = { now: clock.now, ...extra };
  if (config.transport !== 'none') options.transport = makeTransport(log, config.transport);
  const notifier = impl.createNotifier(channel, options);
  const ownStore = extra.throttleStore || notifier.throttleStore;
  const trace = [];

  for (let u = 0; u < USERS.length; u += 1) {
    for (let m = 0; m < MESSAGES.length; m += 1) {
      for (let o = 0; o < SEND_OPTIONS.length; o += 1) {
        const before = clock.calls.length;
        const result = await outcome(() => notifier.send(USERS[u], MESSAGES[m], SEND_OPTIONS[o]));
        trace.push({ u, m, o, result, clockCalls: clock.calls.slice(before) });
      }
    }
  }
  return { trace, log, store: snapshot(ownStore) };
}

function firstDifference(a, b) {
  for (let i = 0; i < Math.max(a.length, b.length); i += 1) {
    try {
      assert.deepStrictEqual(a[i], b[i]);
    } catch {
      return { index: i, legacy: a[i], next: b[i] };
    }
  }
  return null;
}

for (const channel of CHANNELS) {
  for (const config of CONSTRUCTOR_CONFIGS) {
    test(`send matrix matches legacy: ${channel} / ${config.label}`, async () => {
      const a = await runMatrix(legacy, channel, config);
      const b = await runMatrix(next, channel, config);
      const traceDiff = firstDifference(a.trace, b.trace);
      assert.equal(traceDiff, null, `trace differs: ${JSON.stringify(traceDiff, null, 2)}`);
      const logDiff = firstDifference(a.log, b.log);
      assert.equal(logDiff, null, `transport log differs: ${JSON.stringify(logDiff, null, 2)}`);
      assert.deepStrictEqual(b.store, a.store);
      assert.ok(a.trace.some(t => t.result.kind === 'resolve' && t.result.value.status === 'sent') || config.transport,
        'matrix should exercise successful sends');
    });
  }
}

async function runDirectMethods(impl, channel) {
  const clock = makeClock(7);
  const log = [];
  const notifier = impl.createNotifier(channel, { now: clock.now, transport: makeTransport(log), maxPerHour: 2 });
  const results = {};
  const user = USERS[USERS.length - 1];
  const message = MESSAGES[7];

  results.validateUser = await Promise.all(USERS.map(u => outcome(() => notifier.validateUser(u))));
  results.validateMessage = await Promise.all(MESSAGES.map(m => outcome(() => notifier.validateMessage(m))));
  results.applyTemplate = await Promise.all(MESSAGES.filter(Boolean).map(m =>
    outcome(() => notifier.applyTemplate(m.title, user, m))));
  results.throttleKey = await Promise.all(MESSAGES.filter(m => m && typeof m === 'object').map(m =>
    outcome(() => notifier.throttleKey(user, m))));
  results.formatNoOptions = await outcome(() => notifier.format(user, message));
  results.format = await Promise.all(SEND_OPTIONS.map(o => outcome(() => notifier.format(user, message, o))));
  results.shouldThrottleBefore = await Promise.all(SEND_OPTIONS.map(o => outcome(() => notifier.shouldThrottle(user, message, o))));
  results.recordDelivery = [];
  for (let i = 0; i < 3; i += 1) results.recordDelivery.push(await outcome(() => notifier.recordDelivery(user, message)));
  results.shouldThrottleAfter = await Promise.all(SEND_OPTIONS.map(o => outcome(() => notifier.shouldThrottle(user, message, o))));
  results.shouldThrottleNoOptions = await outcome(() => notifier.shouldThrottle(user, message));
  results.deliver = await outcome(() => notifier.deliver({ id: 'manual' }, user, message, {}));
  results.store = snapshot(notifier.throttleStore);
  results.log = log;
  results.clock = clock.calls;
  return results;
}

for (const channel of CHANNELS) {
  test(`stage methods exposed on the notifier match legacy: ${channel}`, async () => {
    assert.deepStrictEqual(await runDirectMethods(next, channel), await runDirectMethods(legacy, channel));
  });

  test(`instance data properties match legacy: ${channel}`, () => {
    const shared = { transport: {}, throttleStore: new Map(), now: () => new Date(START) };
    for (const options of [undefined, {}, shared, CONSTRUCTOR_CONFIGS[2].extra()]) {
      const a = legacy.createNotifier(channel, options);
      const b = next.createNotifier(channel, options);
      const dataKeys = Object.keys(a);
      for (const key of dataKeys) {
        assert.ok(Object.hasOwn(b, key), `missing property ${key}`);
        if (typeof a[key] === 'function') assert.equal(typeof b[key], 'function', key);
        else if (a[key] instanceof Map && !(options && options.throttleStore)) assert.ok(b[key] instanceof Map, key);
        else assert.deepStrictEqual(b[key], a[key], key);
      }
      assert.deepStrictEqual(Object.keys(b).slice(0, dataKeys.length), dataKeys, 'data property order');
      if (options === shared) {
        assert.equal(b.transport, shared.transport);
        assert.equal(b.throttleStore, shared.throttleStore);
        assert.equal(b.now, shared.now);
      }
      assert.ok(b.now() instanceof Date);
      for (const method of ['send', 'validateUser', 'validateMessage', 'shouldThrottle', 'throttleKey',
        'format', 'applyTemplate', 'recordDelivery', 'deliver']) {
        assert.equal(typeof b[method], 'function', method);
      }
    }
  });

  test(`reassigning settings on the notifier affects later sends: ${channel}`, async () => {
    async function run(impl) {
      const logA = [];
      const logB = [];
      const clock = makeClock(0);
      const notifier = impl.createNotifier(channel, { now: clock.now, transport: makeTransport(logA) });
      const user = USERS[USERS.length - 1];
      const message = { title: 't', body: 'b', category: 'general' };
      const out = [await outcome(() => notifier.send(user, message))];
      notifier.transport = makeTransport(logB);
      notifier.maxPerHour = 1;
      out.push(await outcome(() => notifier.send(user, message)));
      notifier.now = makeClock(0, START + 2 * 60 * MINUTE).now;
      notifier.channel = 'renamed';
      out.push(await outcome(() => notifier.send(user, message)));
      out.push(await outcome(() => notifier.send(user, message)));
      notifier.throttleStore = new Map();
      out.push(await outcome(() => notifier.send(user, message)));
      Object.assign(notifier, { from: 'z@z', replyTo: 'r@r', senderId: 'S', segmentLength: 5,
        defaultWorkspace: 'w', defaultChannel: '#d', defaultIcon: 'i', defaultAction: '/a',
        defaultLocale: 'ja-JP', unsubscribeBaseUrl: 'https://unsub' });
      out.push(await outcome(() => notifier.send(user, message, { force: true })));
      return { out, logA, logB };
    }
    assert.deepStrictEqual(await run(next), await run(legacy));
  });
}

test('throttle window boundary and retryAt match legacy', async () => {
  async function run(impl) {
    const clock = makeClock(0);
    const notifier = impl.createNotifier('sms', { now: clock.now, transport: makeTransport([]), maxPerHour: 2 });
    const user = { id: 'b', phone: '+15551234567' };
    const message = { title: 't', body: 'b' };
    const out = [];
    for (const step of [0, 10 * MINUTE, 5 * MINUTE, 44 * MINUTE + 59999, 1, 1, 10 * MINUTE, 60 * MINUTE]) {
