    const viaNew = new next.registry[channel]({ transport: makeTransport([]), now: makeClock(0).now });
    const viaLegacy = new legacy.registry[channel]({ transport: makeTransport([]), now: makeClock(0).now });
    assert.equal(viaNew.channel, viaLegacy.channel);
    assert.equal(typeof viaNew.send, 'function');
