    const notifier = impl.createNotifier('email', {
      now: makeClock(0).now, transport: makeTransport(log, 'async'), maxPerHour: 1
    });
    const user = { id: 'c', email: 'c@example.com' };
    const message = { title: 't', body: 'b' };
    const parallel = await Promise.all([1, 2, 3].map(() => outcome(() => notifier.send(user, message))));
    const after = await outcome(() => notifier.send(user, message));
    return { parallel, after, log, store: snapshot(notifier.throttleStore) };
  }
  assert.deepStrictEqual(await run(next), await run(legacy));
});

