  async function run(impl) {
    const log = [];
    const options = { transport: makeTransport(log), throttleStore: new Map(), now: makeClock(3).now, maxPerHour: 1 };
    const all = impl.createAllNotifiers(options);
    const user = USERS[USERS.length - 1];
    const out = [];
    for (const channel of Object.keys(all)) {
      out.push(await outcome(() => all[channel].send(user, { title: 'a', body: 'b' })));
      out.push(await outcome(() => all[channel].send(user, { title: 'a', body: 'b' })));
    }
    const separate = impl.createAllNotifiers({ transport: makeTransport([]) });
    return {
      keys: Object.keys(all),
      out,
      log,
