});

test('factory API surface matches legacy', async () => {
  assert.deepStrictEqual(Object.keys(next).sort(), Object.keys(legacy).sort());
  assert.deepStrictEqual(Object.keys(next.registry), Object.keys(legacy.registry));
  for (const name of ['fax', '', 'EMAIL', undefined, null, 42]) {
    assert.deepStrictEqual(
      await outcome(() => next.createNotifier(name)),
      await outcome(() => legacy.createNotifier(name)),
      String(name)
    );
  }
  for (const channel of CHANNELS) {
    const viaNew = new next.registry[channel]({ transport: makeTransport([]), now: makeClock(0).now });
    const viaLegacy = new legacy.registry[channel]({ transport: makeTransport([]), now: makeClock(0).now });
    assert.equal(viaNew.channel, viaLegacy.channel);
    assert.equal(typeof viaNew.send, 'function');
    const plainCall = next.registry[channel]({ transport: makeTransport([]) });
    assert.equal(plainCall.channel, channel);
  }
});

test('inherited Object.prototype names are rejected as unknown channels (deliberate change)', async () => {
  for (const name of ['toString', 'constructor', 'hasOwnProperty', '__proto__', 'valueOf']) {
    const result = await outcome(() => next.createNotifier(name, { transport: {} }));
    assert.deepStrictEqual(result, {
      kind: 'sync-throw',
      error: { name: 'TypeError', message: `unknown notification channel: ${name}` }
    }, name);
  }
});

