const HOUR_MS = 60 * 60 * 1000;

/**
 * @typedef {{ throttled: false } | { throttled: true, reason: string, retryAt: string | null }} ThrottleVerdict
 */

/**
 * @typedef {object} ThrottleContext
 * @property {import('./composeNotifier').NotifierConfig} config
 * @property {object} user
 * @property {object} message
 * @property {object} options  Per-send options.
 */

/**
 * A rule returns a verdict to stop evaluation, or null to defer to the next rule.
 * @typedef {(context: ThrottleContext) => ThrottleVerdict | null} ThrottleRule
 */

/**
 * @param {{ channel: string }} config
 * @param {{ id: unknown }} user
 * @param {{ category?: string }} message
 * @returns {string}
 */
function throttleKey(config, user, message) {
  const category = message.category || 'general';
  return `${config.channel}:${user.id}:${category}`;
}

/**
 * Sliding one-hour limit of `config.maxPerHour` deliveries per channel, user and category.
 * `force` and urgent messages skip the limit but not the rules after it.
 * @type {ThrottleRule}
 */
function hourlyLimit({ config, user, message, options }) {
  if (options.force || message.priority === 'urgent') {
    return null;
  }

  const key = throttleKey(config, user, message);
  const now = config.now().getTime();
  const records = (config.throttleStore.get(key) || []).filter(ts => now - ts < HOUR_MS);

  if (records.length >= config.maxPerHour) {
    return {
      throttled: true,
      reason: `${config.channel} hourly limit reached`,
      retryAt: new Date(records[0] + HOUR_MS).toISOString()
    };
  }

  return null;
}

/**
 * Lets the message through, skipping all later rules, when the predicate holds.
 * @param {(context: ThrottleContext) => boolean} predicate
 * @returns {ThrottleRule}
 */
function exemptWhen(predicate) {
  return context => (predicate(context) ? { throttled: false } : null);
}

/**
 * Holds back marketing messages unless `user[optInField]` is truthy. Applies to
 * forced and urgent sends too.
 * @param {string} optInField
 * @param {string} reason
 * @returns {ThrottleRule}
 */
function requireMarketingConsent(optInField, reason) {
  return ({ user, message }) => {
    if (message.category === 'marketing' && !user[optInField]) {
      return { throttled: true, reason, retryAt: null };
    }
    return null;
  };
}

/**
 * @param {ReadonlyArray<ThrottleRule>} rules
 * @param {ThrottleContext} context
 * @returns {ThrottleVerdict}
 */
function evaluateThrottle(rules, context) {
  for (const rule of rules) {
    const verdict = rule(context);
    if (verdict) {
      return verdict;
    }
  }
  return { throttled: false };
}

/**
 * Appends the current time to the store entry that `hourlyLimit` reads.
 * @param {import('./composeNotifier').NotifierConfig} config
 * @param {object} user
 * @param {object} message
 */
function recordDelivery(config, user, message) {
  const key = throttleKey(config, user, message);
  const records = config.throttleStore.get(key) || [];
  records.push(config.now().getTime());
  config.throttleStore.set(key, records);
}

module.exports = {
  throttleKey,
  hourlyLimit,
  exemptWhen,
  requireMarketingConsent,
  evaluateThrottle,
  recordDelivery
};

