/** Default cap on `preview` length; channels may shorten it further. */
const PREVIEW_MAX_LENGTH = 120;

/**
 * @typedef {object} Envelope
 * @property {string} id
 * @property {string} channel
 * @property {string} locale
 * @property {string} title
 * @property {string} body
 * @property {string} preview
 * @property {{ category: string, priority: string, generatedAt: string }} metadata
 */

/**
 * Replaces `{{name}}`, `{{id}}` and `{{category}}` placeholders.
 * @param {unknown} value  Coerced with String().
 * @param {{ id: unknown, name?: string }} user
 * @param {{ category?: string }} message
 * @returns {string}
 */
function applyTemplate(value, user, message) {
  return String(value)
    .replace(/\{\{name\}\}/g, user.name || 'there')
    .replace(/\{\{id\}\}/g, user.id)
    .replace(/\{\{category\}\}/g, message.category || 'general');
}

/**
 * Builds the fields every channel payload starts from.
 * @param {import('./composeNotifier').NotifierConfig} config
 * @param {object} user
 * @param {object} message
 * @param {object} options  Per-send options.
 * @returns {Envelope}
 */
function formatEnvelope(config, user, message, options) {
  const id = `${config.channel}-${user.id}-${config.now().getTime()}`;
  const locale = options.locale || user.locale || config.defaultLocale;
  const title = applyTemplate(message.title, user, message);
  const body = applyTemplate(message.body, user, message);

  return {
    id,
    channel: config.channel,
    locale,
    title,
    body,
    preview: `${title}: ${body}`.slice(0, PREVIEW_MAX_LENGTH),
    metadata: {
      category: message.category || 'general',
      priority: message.priority || 'normal',
      generatedAt: config.now().toISOString()
    }
  };
}

module.exports = {
  PREVIEW_MAX_LENGTH,
  applyTemplate,
  formatEnvelope
};

