/**
 * Creates a deliver step that hands the payload to `transport[transportKey]`.
 * @param {string} transportKey  Property on the transport object, e.g. 'inapp'.
 * @param {string} label  Channel name used in the error message, e.g. 'in-app'.
 * @returns {(transport: object, payload: object) => Promise<void>}
 */
function deliverVia(transportKey, label) {
  return async function deliver(transport, payload) {
    if (typeof transport[transportKey] !== 'function') {
      throw new Error(`${label} transport is not configured`);
    }
    // Called as a method so transports that rely on `this` keep working.
    await transport[transportKey](payload);
  };
}

module.exports = {
  deliverVia
};

