const { hourlyLimit, requireMarketingConsent } = require('../throttling');
const { deliverVia } = require('../delivery');

const EMAIL_PREVIEW_LENGTH = 90;

function validateEmailRecipient(user) {
  if (!user.email || !user.email.includes('@')) {
    throw new TypeError('user.email is required for email notifications');
  }
}

function escapeHtml(value) {
  return String(value)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;');
}

function footerFor(config, user, message) {
  if (message.category === 'transactional' || message.category === 'security') {
    return `Sent to ${user.email} because of recent account activity.`;
  }
  const url = `${config.unsubscribeBaseUrl}?user=${encodeURIComponent(user.id)}`;
  return `You can unsubscribe at ${url}.`;
}

function formatEmail(envelope, { config, user, message }) {
  const subjectPrefix = message.category === 'security' ? '[Action Required] ' : '';
  const footer = footerFor(config, user, message);

  return {
    ...envelope,
    to: user.email,
    from: config.from,
    replyTo: config.replyTo,
    subject: `${subjectPrefix}${envelope.title}`,
    text: `${envelope.body}\n\n${footer}`,
    html: `<h1>${escapeHtml(envelope.title)}</h1><p>${escapeHtml(envelope.body)}</p><footer>${escapeHtml(footer)}</footer>`,
    preview: envelope.body.slice(0, EMAIL_PREVIEW_LENGTH)
  };
}

/** @type {import('../composeNotifier').ChannelStrategy} */
const emailChannel = Object.freeze({
  name: 'email',
  defaultMaxPerHour: 8,
  resolveSettings: options => ({
    from: options.from || 'noreply@example.com',
    replyTo: options.replyTo || 'support@example.com',
    unsubscribeBaseUrl: options.unsubscribeBaseUrl || 'https://example.com/unsubscribe'
  }),
  validateUser: validateEmailRecipient,
  throttleRules: Object.freeze([
    hourlyLimit,
    requireMarketingConsent('emailOptIn', 'user has not opted into marketing email')
  ]),
  format: formatEmail,
  deliver: deliverVia('email', 'email')
});

module.exports = {
  emailChannel
};

