const { hourlyLimit, requireMarketingConsent } = require('../throttling');
const { deliverVia } = require('../delivery');

const E164_PATTERN = /^\+[1-9]\d{6,14}$/;
const DEFAULT_SEGMENT_LENGTH = 140;

function validateSmsRecipient(user) {
  if (!user.phone || !E164_PATTERN.test(user.phone)) {
    throw new TypeError('user.phone must be E.164 for SMS notifications');
  }
}

// Lengths are UTF-16 code units, so a cut can split a surrogate pair.
function truncate(value, maxLength) {
  if (value.length <= maxLength) {
    return value;
  }
  return `${value.slice(0, maxLength - 1)}…`;
}

function formatSms(envelope, { config, user, message }) {
  const prefix = message.priority === 'urgent' ? 'URGENT: ' : '';
  const composed = `${prefix}${envelope.title} - ${envelope.body}`;
  const text = truncate(composed, config.segmentLength);

  return {
    ...envelope,
    to: user.phone,
    from: config.senderId,
    text,
    segments: Math.ceil(text.length / config.segmentLength),
    preview: text
  };
}

/** @type {import('../composeNotifier').ChannelStrategy} */
const smsChannel = Object.freeze({
  name: 'sms',
  defaultMaxPerHour: 4,
  resolveSettings: options => ({
    senderId: options.senderId || 'APP',
    segmentLength: options.segmentLength || DEFAULT_SEGMENT_LENGTH
  }),
  validateUser: validateSmsRecipient,
  throttleRules: Object.freeze([
    hourlyLimit,
    requireMarketingConsent('smsOptIn', 'user has not opted into marketing SMS')
  ]),
  format: formatSms,
  deliver: deliverVia('sms', 'sms')
});

module.exports = {
  smsChannel
};

