const { composeNotifier } = require('./composeNotifier');
const { emailChannel } = require('./channels/email');
const { smsChannel } = require('./channels/sms');
const { slackChannel } = require('./channels/slack');
const { inAppChannel } = require('./channels/inapp');

function notifierFactory(strategy) {
  // A regular function, not an arrow: registry entries used to be classes, and
  // `new registry.email(options)` still returns the composed notifier this way.
  return function createChannelNotifier(options) {
    return composeNotifier(strategy, options);
  };
}

/** Channel name to notifier factory. */
const registry = {
  email: notifierFactory(emailChannel),
  sms: notifierFactory(smsChannel),
  slack: notifierFactory(slackChannel),
  inapp: notifierFactory(inAppChannel)
};

/**
 * @param {string} channel  One of the `registry` keys.
 * @param {object} [options]
 * @throws {TypeError} for a channel that is not an own key of `registry`
 */
function createNotifier(channel, options = {}) {
  const factory = Object.hasOwn(registry, channel) ? registry[channel] : undefined;
  if (!factory) {
    throw new TypeError(`unknown notification channel: ${channel}`);
  }
  return factory(options);
}

/**
 * Creates one notifier per registered channel, all built from the same options.
 * @param {object} [options]
 * @returns {Record<string, ReturnType<typeof createNotifier>>}
 */
function createAllNotifiers(options = {}) {
  return Object.keys(registry).reduce((all, channel) => {
    all[channel] = createNotifier(channel, options);
    return all;
  }, {});
}

module.exports = {
  createNotifier,
  createAllNotifiers,
  registry
};

