  const u = { id: 'c', email: 'c@x' }, m = { title: 't', body: 'b' };
  const res = await Promise.all([1,2,3].map(() => n.send(u, m)));
  console.log('concurrent legacy statuses:', res.map(r => r.status).join(','));
  const f = legacy.createNotifier('sms', { maxPerHour: 1, transport: { sms: async () => { throw new RangeError('down'); } } });
  await f.send({ id: 'x', phone: '+15551234567' }, m).catch(e => console.log('failed delivery error:', e.constructor.name, e.message, '| store size:', f.throttleStore.size));
})();
