node -e "
const { createNotifier, createAllNotifiers } = require('./src/notifications');
const user = { id: 'u', name: 'N', email: 'a@b', phone: '+15551234567', slackId: 'U', slackChannel: '#c', emailOptIn: true, smsOptIn: true, locale: 'fr-FR' };
const message = { title: 'Hi {{name}}', body: '<b>{{category}}</b>', category: 'marketing', priority: 'urgent', icon: 'x', actionUrl: '/y', meta: { nested: [1] } };
const sendOptions = { locale: 'de-DE', channel: '#o', threadTs: '1', actionUrl: '/z', expiresInHours: 2, force: true };
const factoryOptions = { transport: { email() {}, sms() {}, slack() {}, inapp() {} }, maxPerHour: 1, now: () => new Date(0) };
const snap = () => JSON.stringify([user, message, sendOptions, Object.keys(factoryOptions), factoryOptions.maxPerHour]);
const before = snap();
(async () => {
  for (const n of Object.values(createAllNotifiers(factoryOptions))) {
    await n.send(user, message, sendOptions); await n.send(user, message);
    n.format(user, message, sendOptions); n.shouldThrottle(user, message, sendOptions); n.validateUser(user);
  }
  console.log(snap() === before ? 'caller inputs unchanged' : 'MUTATED: ' + snap());
  try { createNotifier('email', null); } catch (e) { console.log('null options:', e.constructor.name, '-', e.message); }
})();
"

